package com.sintax;

public class CastImplicitoEsplicito {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		// CAST IMPLICITO
		int number = 3;
		float numbers = number;
		
		System.out.println("VALORE int: " + number);
		System.out.println("CAST IMPLICITO DA int a float: " + numbers);

		
		// CAST ESPLICITO
		double d1 = 100;
		float f1 = (float) d1;
		
		System.out.println("VALORE double: " + d1);		
		System.out.println("CAST ESPLICITO DA double a float: " + f1);
		
		//long cf = "VSPFNC87L27C352W";
		
		/*
		 * Questo è un 
		 * commento 
		 * multiriga
		 * */
		
		
		
		
		
		
		
	}

}
